34	// InitRepo initializes a git repository in the given directory with test user config.
35	func InitRepo(t *testing.T, repoDir string) {
36		t.Helper()
37	
38		repo, err := git.PlainInit(repoDir, false)
39		if err != nil {
40			t.Fatalf("failed to init git repo: %v", err)
41		}
42		defer repo.Close()
43	
44		// Configure git user for commits
45		cfg, err := repo.Config()
46		if err != nil {
47			t.Fatalf("failed to get repo config: %v", err)
48		}
49		cfg.User.Name = "Test User"
50		cfg.User.Email = "test@example.com"
51	
52		// Disable GPG signing for test commits
53		if cfg.Raw == nil {
54			cfg.Raw = config.New()
55		}
56		cfg.Raw.Section("commit").SetOption("gpgsign", "false")
