158	// RunGit runs one git command in dir with an isolated git config, failing the
159	// test on error and returning combined output. Use it for operations go-git
160	// cannot express (force-add past .gitignore, rm --cached, worktree add) or
161	// where shelling out is simply clearer.
162	func RunGit(t *testing.T, dir string, args ...string) string {
